"""Textures generated by the Lab for its teaching effects."""

from pathlib import Path
from typing import Callable
import math
import struct
import zlib

RGB = tuple[int, int, int]

def png(path: Path, w: int, h: int, sample: Callable[[int, int], RGB]) -> None:
    def chunk(tag: bytes, data: bytes) -> bytes:
        return struct.pack(">I", len(data)) + tag + data + struct.pack(">I", zlib.crc32(tag + data))

    raw = b"".join(b"\0" + bytes(c for x in range(w) for c in sample(x, y)) for y in range(h))
    header = struct.pack(">IIBBBBB", w, h, 8, 2, 0, 0, 0)
    path.write_bytes(
        b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", header) + chunk(b"IDAT", zlib.compress(raw)) + chunk(b"IEND", b"")
    )


def smoke_sprite(path: Path) -> None:
    """Soft-edged RGBA puff with multiscale billows and transparent borders."""
    def chunk(tag: bytes, data: bytes) -> bytes:
        return struct.pack(">I", len(data)) + tag + data + struct.pack(">I", zlib.crc32(tag + data))

    def sample(x: int, y: int) -> tuple[int, int, int, int]:
        u, v = (x-63.5)/63.5, (y-63.5)/63.5
        wobble = .085*math.sin(14*u+5*v) + .049*math.sin(23*v-6*u) + .025*math.sin(39*u+21*v)
        radius = math.hypot(u+.08*math.sin(5*v), v)
        edge = min(1, max(0, (1-radius+wobble)*2.15))
        alpha = edge*edge*(3-2*edge)
        grain = .5+.5*math.sin(11*u+7*v)*math.sin(8*v-4*u)
        value = round(192 + 62*grain)
        return value, value, value, round(240*alpha*(.66+.34*grain))

    pixels = b"".join(b"\0" + bytes(c for x in range(128) for c in sample(x, y)) for y in range(128))
    header = struct.pack(">IIBBBBB", 128, 128, 8, 6, 0, 0, 0)
    path.write_bytes(
        b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", header) + chunk(b"IDAT", zlib.compress(pixels)) + chunk(b"IEND", b"")
    )


def write_resources(root: Path) -> None:
    maps = root / "maps"
    maps.mkdir(parents=True, exist_ok=True)
    smoke_sprite(maps / "practice-smoke.png")
    for name, scale, offset in (
        ("neutral", (1, 1, 1), (0, 0, 0)),
        ("day", (1.06, 1.00, .89), (.018, .010, .016)),
        ("night", (.73, .85, 1.04), (.019, .029, .062)),
    ):
        def lut(x: int, y: int) -> tuple[int, int, int]:
            # File rows start at green=0; upload flips Y. Shader reads 15-green.
            rgb = ((x % 16)/15, y/15, (x//16)/15)
            return tuple(round(255*min(1, max(0, v*s+b))) for v, s, b in zip(rgb, scale, offset))
        png(maps / f"practice-{name}-lut.png", 256, 16, lut)

    def flow(x: int, y: int) -> tuple[int, int, int]:
        u, v = x*math.tau/64, y*math.tau/64
        return round(141 + 9*math.sin(v) + 4*math.cos(u+v)), round(120 + 8*math.sin(u-v)), 0
    png(maps / "practice-flow.png", 64, 64, flow)
